// Copies the Lucide glyphs the newsletter's amenity icons use into
// lib/newsletter/blocks/amenity-glyphs.ts, as SVG markup the icon route
// (app/api/newsletter/icon) rasterises in any colour.
//
// Reads the glyph names from lib/newsletter/blocks/amenity-icons.ts, so after
// adding an icon there run `node scripts/email/amenity-icons.mjs` and commit
// the regenerated file. Lucide is ISC-licensed; its notice is kept in the
// output.
import { readFileSync, writeFileSync } from "node:fs";

const CATALOGUE = "lib/newsletter/blocks/amenity-icons.ts";
const OUT = "lib/newsletter/blocks/amenity-glyphs.ts";
const ICONS = "node_modules/lucide-react/dist/esm/icons";

const names = [...new Set([...readFileSync(CATALOGUE, "utf8").matchAll(/glyph: "([a-z0-9-]+)"/g)].map((m) => m[1]))].sort();
const version = JSON.parse(readFileSync("node_modules/lucide-react/package.json", "utf8")).version;

const attr = (v) => String(v).replaceAll("&", "&amp;").replaceAll('"', "&quot;");

const glyphs = {};
for (const name of names) {
  let src = readFileSync(`${ICONS}/${name}.mjs`, "utf8");
  // Renamed glyphs keep their old name as a re-export ("waves" → "waves-horizontal").
  for (let alias; (alias = /export \{ default \} from '\.\/([a-z0-9-]+)\.mjs'/.exec(src)); ) {
    src = readFileSync(`${ICONS}/${alias[1]}.mjs`, "utf8");
  }
  const m = /const __iconNode = (\[[\s\S]*?\]);\n/.exec(src);
  if (!m) throw new Error(`no icon node in ${name}`);
  const node = new Function(`return ${m[1]}`)();
  glyphs[name] = node
    .map(([tag, attrs]) => {
      const a = Object.entries(attrs)
        .filter(([k]) => k !== "key")
        .map(([k, v]) => `${k}="${attr(v)}"`)
        .join(" ");
      return `<${tag} ${a}/>`;
    })
    .join("");
}

const body = Object.entries(glyphs)
  .map(([k, v]) => `  ${JSON.stringify(k)}: ${JSON.stringify(v)},`)
  .join("\n");
writeFileSync(
  OUT,
  `/**
 * GENERATED by scripts/email/amenity-icons.mjs — do not edit by hand.
 *
 * The inner SVG of each Lucide glyph an amenity icon draws (24×24 viewBox,
 * stroked, no fill), for app/api/newsletter/icon. Lucide ${version}, ISC licence:
 * https://github.com/lucide-icons/lucide/blob/main/LICENSE
 */

export const AMENITY_GLYPHS: Record<string, string> = {
${body}
};
`,
);
console.log(`wrote ${names.length} glyphs to ${OUT}`);
